use clap::{App, AppSettings, Arg, SubCommand};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, exit};

#[derive(Serialize, Deserialize, Debug, Clone)]
struct Script {
    command: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    tags: Option<Vec<String>>,
}

#[derive(Serialize, Deserialize, Debug, Clone, Default)]
struct DefaultOptions {
    #[serde(skip_serializing_if = "Option::is_none")]
    command_width: Option<usize>,
}

#[derive(Serialize, Deserialize, Debug, Clone, Default)]
struct Config {
    #[serde(default)]
    scripts: BTreeMap<String, Script>,
    #[serde(default)]
    default: DefaultOptions,
}

impl Config {
    fn load(path: &Path) -> Result<Self, Box<dyn std::error::Error>> {
        let content = fs::read_to_string(path)?;
        let config: Config = toml::from_str(&content)?;
        Ok(config)
    }

    fn save(&self, path: &Path) -> Result<(), Box<dyn std::error::Error>> {
        let content = toml::to_string_pretty(self)?;
        fs::write(path, content)?;
        Ok(())
    }
}

fn find_config() -> Option<PathBuf> {
    if let Ok(path) = env::var("PIER_CONFIG_PATH") {
        if !path.is_empty() {
            return Some(PathBuf::from(path));
        }
    }
    if Path::new("pier.toml").exists() {
        return Some(PathBuf::from("pier.toml"));
    }

    let xdg_config_home = env::var("XDG_CONFIG_HOME")
        .map(PathBuf::from)
        .ok()
        .or_else(|| dirs::home_dir().map(|h| h.join(".config")));

    if let Some(xdg) = xdg_config_home {
        let paths = vec![
            xdg.join("pier/config.toml"),
            xdg.join("pier/config"),
            xdg.join("pier.toml"),
        ];
        for p in paths {
            if p.exists() {
                return Some(p);
            }
        }
    }
    if let Some(home) = dirs::home_dir() {
        let paths = vec![
            home.join(".pier.toml"),
            home.join(".pier"),
        ];
        for p in paths {
            if p.exists() {
                return Some(p);
            }
        }
    }
    None
}

fn open_editor(initial_content: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut temp = tempfile::NamedTempFile::new()?;
    temp.write_all(initial_content.as_bytes())?;
    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());

    let status = Command::new(&editor)
        .arg(temp.path())
        .status();

    match status {
        Ok(s) if s.success() => {
            let mut content = fs::read_to_string(temp.path())?;
            if content.ends_with('\n') {
                content.pop();
            }
            Ok(content)
        }
        _ => {
            Err(format!("EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.", editor).into())
        }
    }
}

fn main() {
    let mut app = App::new("pier")
        .version("0.1.6")
        .author("Benjamin Scholtz, Isak Johansson")
        .about("A simple script management CLI")
        .setting(AppSettings::DeriveDisplayOrder)
        .setting(AppSettings::SubcommandRequiredElseHelp)
        .arg(Arg::with_name("config-file")
            .short("c")
            .long("config-file")
            .help("Sets a custom config file.")
            .takes_value(true)
            .global(true)
        )
        .arg(Arg::with_name("verbose")
            .short("v")
            .long("verbose")
            .help("The level of verbosity")
            .global(true)
        )
        .subcommand(SubCommand::with_name("add")
            .about("Add a new script to config.")
            .arg(Arg::with_name("alias")
                .short("a")
                .long("alias")
                .help("The alias or name for the script.")
                .required(true)
                .takes_value(true))
            .arg(Arg::with_name("description")
                .short("d")
                .long("description")
                .help("The description for the script.")
                .takes_value(true))
            .arg(Arg::with_name("tag")
                .short("t")
                .long("tag")
                .help("Set which tags the script belongs to.")
                .multiple(true)
                .takes_value(true))
            .arg(Arg::with_name("force")
                .short("f")
                .long("force")
                .help("Allows to overwrite the existing script"))
            .arg(Arg::with_name("command")
                .help("The command/script content to be executed. If this argument is not found it will open your $EDITOR for you to enter the script into.")
                .index(1))
        )
        .subcommand(SubCommand::with_name("config-init")
            .alias("init")
            .about("Add a config file.")
        )
        .subcommand(SubCommand::with_name("copy")
            .alias("cp")
            .about("Copy existing alias to the new one")
            .arg(Arg::with_name("from-alias")
                .help("The alias of the script that will be copied.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("to-alias")
                .help("The new alias of the copy of the script.")
                .required(true)
                .index(2))
        )
        .subcommand(SubCommand::with_name("edit")
            .about("Edit a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1))
        )
        .subcommand(SubCommand::with_name("list")
            .alias("ls")
            .about("List scripts")
            .arg(Arg::with_name("cmd_full")
                .short("l")
                .long("cmd_full")
                .help("Display the full command."))
            .arg(Arg::with_name("list_aliases")
                .short("q")
                .long("list_aliases")
                .help("Only displays aliases of the scripts."))
            .arg(Arg::with_name("cmd_width")
                .short("c")
                .long("cmd_width")
                .help("The max number of characters to display from the command.")
                .takes_value(true))
            .arg(Arg::with_name("tag")
                .short("t")
                .long("tag")
                .help("Filter based on tags.")
                .multiple(true)
                .takes_value(true))
        )
        .subcommand(SubCommand::with_name("move")
            .alias("mv")
            .alias("rename")
            .about("Move/rename existing alias to the new one")
            .arg(Arg::with_name("from-alias")
                .help("The alias of the script that will be moved.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("to-alias")
                .help("The new alias of the script.")
                .required(true)
                .index(2))
            .arg(Arg::with_name("force")
                .short("f")
                .long("force")
                .help("Allows to overwrite the existing script"))
        )
        .subcommand(SubCommand::with_name("remove")
            .alias("rm")
            .about("Remove a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1))
        )
        .subcommand(SubCommand::with_name("run")
            .about("Run a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("args")
                .help("The positional arguments to send to script.")
                .multiple(true)
                .index(2))
        )
        .subcommand(SubCommand::with_name("show")
            .about("Show a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1))
        );

    // To handle the <alias> [args]... case, we need to manually inspect arguments
    // before passing them to clap, or use a different clap configuration.
    // However, the provided executable seems to handle it by attempting to match subcommands first.

    let args: Vec<String> = env::args().collect();
    let mut config_path_from_args = None;
    for i in 1..args.len() {
        if args[i] == "-c" || args[i] == "--config-file" {
            if i + 1 < args.len() {
                config_path_from_args = Some(PathBuf::from(&args[i+1]));
            }
        }
    }

    let config_path = config_path_from_args.or_else(find_config);

    if args.len() > 1 {
        let first_arg = &args[1];
        let subcommands = vec!["add", "config-init", "init", "copy", "cp", "edit", "list", "ls", "move", "mv", "rename", "remove", "rm", "run", "show", "help"];

        if !first_arg.starts_with('-') && !subcommands.contains(&first_arg.as_str()) {
            // It might be an alias. Let's try to load config and check.
            if let Some(path) = &config_path {
                if let Ok(config) = Config::load(path) {
                    if config.scripts.contains_key(first_arg) {
                        // It is an alias! Rewrite args to use 'run' subcommand.
                        let mut new_args = vec![args[0].clone(), "run".to_string()];
                        new_args.extend(args[1..].iter().cloned());

                        let matches = app.get_matches_from(new_args);
                        handle_matches(matches, &config_path, &app);
                        return;
                    }
                }
            }
        }
    }

    let matches = app.get_matches();
    handle_matches(matches, &config_path, &app);
}

fn handle_matches(matches: clap::ArgMatches, config_path: &Option<PathBuf>, app: &App) {
    let verbose = matches.is_present("verbose");

    if let Some(sub_m) = matches.subcommand_matches("config-init") {
        config_init();
        return;
    }

    let path = match config_path {
        Some(p) => p,
        None => {
            eprintln!("error: No default config file found. See help for more info.");
            exit(1);
        }
    };

    let mut config = match Config::load(path) {
        Ok(c) => c,
        Err(e) => {
            // If it's a 'run' command and we're here, maybe it's because it couldn't find the alias?
            // No, it's because it couldn't load the config.
            eprintln!("error: {}", e);
            exit(1);
        }
    };

    match matches.subcommand() {
        ("add", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap().to_string();
            if config.scripts.contains_key(&alias) && !sub_m.is_present("force") {
                eprintln!("error: AliasAlreadyExists:  {}", alias);
                exit(1);
            }
            let command = if let Some(cmd) = sub_m.value_of("command") {
                cmd.to_string()
            } else {
                match open_editor("") {
                    Ok(cmd) => cmd,
                    Err(e) => {
                        eprintln!("error: {}", e);
                        exit(1);
                    }
                }
            };
            let description = sub_m.value_of("description").map(|s| s.to_string());
            let tags = sub_m.values_of("tag").map(|vs| vs.map(|s| s.to_string()).collect());
            config.scripts.insert(alias.clone(), Script { command, description, tags });
            config.save(path).unwrap();
            println!("Added {}", alias);
        }
        ("copy", Some(sub_m)) => {
            let from = sub_m.value_of("from-alias").unwrap();
            let to = sub_m.value_of("to-alias").unwrap();
            if !config.scripts.contains_key(from) {
                eprintln!("error: AliasNotFound: No script found by alias {}", from);
                exit(1);
            }
            if config.scripts.contains_key(to) {
                eprintln!("error: AliasAlreadyExists:  {}", to);
                exit(1);
            }
            let script = config.scripts.get(from).unwrap().clone();
            config.scripts.insert(to.to_string(), script);
            config.save(path).unwrap();
            println!("Copy from alias {} to new alias {}", from, to);
        }
        ("edit", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap();
            if let Some(script) = config.scripts.get_mut(alias) {
                match open_editor(&script.command) {
                    Ok(cmd) => {
                        script.command = cmd;
                        config.save(path).unwrap();
                        println!("Edited {}", alias);
                    }
                    Err(e) => {
                        eprintln!("error: {}", e);
                        exit(1);
                    }
                }
            } else {
                eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                exit(1);
            }
        }
        ("list", Some(sub_m)) => {
            list_scripts(&config, sub_m);
        }
        ("move", Some(sub_m)) => {
            let from = sub_m.value_of("from-alias").unwrap();
            let to = sub_m.value_of("to-alias").unwrap();
            if !config.scripts.contains_key(from) {
                eprintln!("error: AliasNotFound: No script found by alias {}", from);
                exit(1);
            }
            if config.scripts.contains_key(to) && !sub_m.is_present("force") {
                eprintln!("error: AliasAlreadyExists:  {}", to);
                exit(1);
            }
            let script = config.scripts.remove(from).unwrap();
            config.scripts.insert(to.to_string(), script);
            config.save(path).unwrap();
            println!("Move from alias {} to new alias {}", from, to);
        }
        ("remove", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap();
            if config.scripts.remove(alias).is_some() {
                config.save(path).unwrap();
                println!("Removed {}", alias);
            } else {
                eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                exit(1);
            }
        }
        ("run", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap();
            let args: Vec<&str> = sub_m.values_of("args").unwrap_or_default().collect();
            if let Some(script) = config.scripts.get(alias) {
                run_script(alias, script, &args, verbose);
            } else {
                eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                exit(1);
            }
        }
        ("show", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap();
            if let Some(script) = config.scripts.get(alias) {
                println!("{}", script.command);
            } else {
                eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                exit(1);
            }
        }
        _ => {}
    }
}

fn config_init() {
    let xdg_config_home = env::var("XDG_CONFIG_HOME")
        .map(PathBuf::from)
        .ok()
        .or_else(|| dirs::home_dir().map(|h| h.join(".config")));

    if let Some(xdg) = xdg_config_home {
        let pier_dir = xdg.join("pier");
        if !pier_dir.exists() {
            if let Err(e) = fs::create_dir(&pier_dir) {
                eprintln!("error: Failed to create directory. {}", e);
                exit(1);
            }
        }
        let config_path = pier_dir.join("config.toml");
        if config_path.exists() {
            eprintln!("error: Cannot initialize config at {}, file already exists.", config_path.display());
            exit(1);
        }
        let mut config = Config::default();
        config.scripts.insert("hello-pier".to_string(), Script {
            command: "echo Hello, Pier!".to_string(),
            description: Some("This is an example command.".to_string()),
            tags: None,
        });
        if let Err(e) = config.save(&config_path) {
            eprintln!("error: Failed to save config. {}", e);
            exit(1);
        }
        println!("Added hello-pier");
    } else {
        eprintln!("error: Could not find config directory.");
        exit(1);
    }
}

fn list_scripts(config: &Config, sub_m: &clap::ArgMatches) {
    if sub_m.is_present("list_aliases") {
        for alias in config.scripts.keys() {
            println!("{}", alias);
        }
        return;
    }

    let filter_tags: Vec<&str> = sub_m.values_of("tag").unwrap_or_default().collect();
    let scripts: Vec<(&String, &Script)> = config.scripts.iter()
        .filter(|(_, s)| {
            if filter_tags.is_empty() {
                return true;
            }
            if let Some(tags) = &s.tags {
                for ft in &filter_tags {
                    if tags.contains(&ft.to_string()) {
                        return true;
                    }
                }
            }
            false
        })
        .collect();

    let mut alias_width = 5; // "Alias"
    let mut tags_width = 4; // "Tags"
    let mut cmd_width = 7; // "Command"
    let mut desc_width = 11; // "Description"

    let mut display_scripts = Vec::new();
    for (alias, script) in scripts {
        let tags = script.tags.as_ref().map(|t| t.join(",")).unwrap_or_default();
        let cmd = if sub_m.is_present("cmd_full") {
            script.command.clone()
        } else if let Some(width) = sub_m.value_of("cmd_width").and_then(|w| w.parse::<usize>().ok()) {
            script.command.chars().take(width).collect()
        } else if let Some(width) = config.default.command_width {
            script.command.chars().take(width).collect()
        } else {
            script.command.clone()
        };
        let desc = script.description.as_deref().unwrap_or_default().to_string();

        alias_width = alias_width.max(alias.len());
        tags_width = tags_width.max(tags.len());
        cmd_width = cmd_width.max(cmd.len());
        desc_width = desc_width.max(desc.len());

        display_scripts.push((alias, tags, cmd, desc));
    }

    let total_width = alias_width + tags_width + cmd_width + desc_width + 5 + 4*2;
    // Wait, my previous calculation was:
    // (alias_width+2) + (tags_width+2) + (cmd_width+2) + (desc_width+2) + 5 = total_width
    let line: String = std::iter::repeat('≖').take(alias_width + tags_width + cmd_width + desc_width + 13).collect();
    println!("{}", line);
    println!("⋮ {:<aw$} ⋮ {:<tw$} ⋮ {:<cw$} ⋮ {:<dw$} ⋮", "Alias", "Tags", "Command", "Description", aw=alias_width, tw=tags_width, cw=cmd_width, dw=desc_width);
    println!("{}", line);
    for (alias, tags, cmd, desc) in display_scripts {
        println!("⋮ {:<aw$} ⋮ {:<tw$} ⋮ {:<cw$} ⋮ {:<dw$} ⋮", alias, tags, cmd, desc, aw=alias_width, tw=tags_width, cw=cmd_width, dw=desc_width);
    }
    println!("{}", line);
}

fn run_script(alias: &str, script: &Script, args: &[&str], verbose: bool) {
    if verbose {
        println!("Starting script \"{}\"", alias);
        println!("-------------------------");
    }

    let mut cmd = Command::new("sh");
    cmd.arg("-c").arg(&script.command).arg(alias);
    for arg in args {
        cmd.arg(arg);
    }

    let status = cmd.status();

    if verbose {
        println!("-------------------------");
        println!("Script complete");
    }

    match status {
        Ok(s) => {
            if let Some(code) = s.code() {
                exit(code);
            }
        }
        Err(e) => {
            eprintln!("error: {}", e);
            exit(1);
        }
    }
}
