use clap::{App, AppSettings, Arg, SubCommand};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, exit};

#[derive(Serialize, Deserialize, Debug, Clone)]
struct Script {
    command: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    tags: Option<Vec<String>>,
}

#[derive(Serialize, Deserialize, Debug, Clone, Default)]
struct DefaultOptions {
    #[serde(skip_serializing_if = "Option::is_none")]
    command_width: Option<usize>,
}

#[derive(Serialize, Deserialize, Debug, Clone, Default)]
struct Config {
    #[serde(default)]
    scripts: BTreeMap<String, Script>,
    #[serde(default)]
    default: DefaultOptions,
}

impl Config {
    fn load(path: &Path) -> Result<Self, String> {
        let content = fs::read_to_string(path).map_err(|e| format!("Unable to read config from file {}: {}", path.display(), e))?;
        let config: Config = toml::from_str(&content).map_err(|e| format!("Unable to parse config from file {}: {}", path.display(), e))?;
        Ok(config)
    }

    fn save(&self, path: &Path) -> Result<(), Box<dyn std::error::Error>> {
        let content = toml::to_string_pretty(self)?;
        fs::write(path, content)?;
        Ok(())
    }
}

fn find_config() -> Option<PathBuf> {
    if let Ok(path) = env::var("PIER_CONFIG_PATH") {
        if !path.is_empty() {
            return Some(PathBuf::from(path));
        }
    }
    if Path::new("pier.toml").exists() {
        return Some(PathBuf::from("pier.toml"));
    }
    let xdg_config_home = env::var("XDG_CONFIG_HOME")
        .map(PathBuf::from)
        .ok()
        .or_else(|| dirs::home_dir().map(|h| h.join(".config")));

    if let Some(xdg) = xdg_config_home {
        let paths = vec![
            xdg.join("pier/config.toml"),
            xdg.join("pier/config"),
            xdg.join("pier.toml"),
        ];
        for p in paths {
            if p.exists() {
                return Some(p);
            }
        }
    }
    if let Some(home) = dirs::home_dir() {
        let paths = vec![
            home.join(".pier.toml"),
            home.join(".pier"),
        ];
        for p in paths {
            if p.exists() {
                return Some(p);
            }
        }
    }
    None
}

fn open_editor(initial_content: &str) -> Result<String, String> {
    let mut temp = tempfile::NamedTempFile::new().map_err(|e| e.to_string())?;
    temp.write_all(initial_content.as_bytes()).map_err(|e| e.to_string())?;
    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());
    let status = Command::new(&editor)
        .arg(temp.path())
        .status();
    match status {
        Ok(s) if s.success() => {
            let mut content = fs::read_to_string(temp.path()).map_err(|e| e.to_string())?;
            if content.ends_with('\n') {
                content.pop();
            }
            Ok(content)
        }
        _ => {
            Err(format!("EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.", editor))
        }
    }
}

fn main() {
    let app = App::new("pier")
        .version("0.1.6")
        .author("Benjamin Scholtz, Isak Johansson")
        .about("A simple script management CLI")
        .setting(AppSettings::DeriveDisplayOrder)
        .arg(Arg::with_name("config-file")
