    temp.write_all(initial_content.as_bytes()).map_err(|e| e.to_string())?;
    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());
    let status = Command::new(&editor)
        .arg(temp.path())
        .status();
    match status {
        Ok(s) if s.success() => {
            let mut content = fs::read_to_string(temp.path()).map_err(|e| e.to_string())?;
            if content.ends_with('\n') {
                content.pop();
            }
            Ok(content)
        }
        _ => {
            Err(format!("EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.", editor))
        }
    }
}

fn main() {
    let app = App::new("pier")
        .version("0.1.6")
        .author("Benjamin Scholtz, Isak Johansson")
        .about("A simple script management CLI")
        .setting(AppSettings::DeriveDisplayOrder)
        .arg(Arg::with_name("config-file")
            .short("c")
            .long("config-file")
            .help("Sets a custom config file.")
            .takes_value(true)
            .global(true)
        )
        .arg(Arg::with_name("verbose")
            .short("v")
            .long("verbose")
            .help("The level of verbosity")
            .global(true)
