            .about("Run a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("args")
                .help("The positional arguments to send to script.")
                .multiple(true)
                .index(2))
        )
        .subcommand(SubCommand::with_name("show")
            .about("Show a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1))
        );

    let matches = app.clone().get_matches();
    let verbose = matches.is_present("verbose");
    let config_path_arg = matches.value_of("config-file").map(PathBuf::from);

    if let Some(_sub_m) = matches.subcommand_matches("config-init") {
        config_init();
        return;
    }

    let config_path = match config_path_arg.or_else(find_config) {
        Some(p) => p,
        None => {
            if matches.value_of("alias").is_none() && matches.subcommand_name().is_none() {
                app.clone().print_help().unwrap();
                println!();
                return;
            }
            eprintln!("error: No default config file found. See help for more info.");
            exit(1);
        }
    };

    let mut config = match Config::load(&config_path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: {}", e);
            exit(1);
        }
    };

    match matches.subcommand() {
        ("add", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap().to_string();
            if config.scripts.contains_key(&alias) && !sub_m.is_present("force") {
                eprintln!("error: AliasAlreadyExists:  {}", alias);
                exit(1);
            }
            let command = if let Some(cmd) = sub_m.value_of("command") {
                cmd.to_string()
            } else {
                match open_editor("") {
                    Ok(cmd) => cmd,
                    Err(e) => {
                        eprintln!("error: {}", e);
                        exit(1);
                    }
                }
            };
            let description = sub_m.value_of("description").map(|s| s.to_string());
            let tags = sub_m.values_of("tag").map(|vs| vs.map(|s| s.to_string()).collect());
            config.scripts.insert(alias.clone(), Script { command, description, tags });
            config.save(&config_path).unwrap();
            println!("Added {}", alias);
        }
        ("copy", Some(sub_m)) => {
            let from = sub_m.value_of("from-alias").unwrap();
            let to = sub_m.value_of("to-alias").unwrap();
            if !config.scripts.contains_key(from) {
                eprintln!("error: AliasNotFound: No script found by alias {}", from);
                exit(1);
            }
            if config.scripts.contains_key(to) {
                eprintln!("error: AliasAlreadyExists:  {}", to);
                exit(1);
            }
            let script = config.scripts.get(from).unwrap().clone();
            config.scripts.insert(to.to_string(), script);
            config.save(&config_path).unwrap();
            println!("Copy from alias {} to new alias {}", from, to);
        }
        ("edit", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap();
            if let Some(script) = config.scripts.get_mut(alias) {
                match open_editor(&script.command) {
                    Ok(cmd) => {
                        script.command = cmd;
                        config.save(&config_path).unwrap();
                        println!("Edited {}", alias);
                    }
                    Err(e) => {
                        eprintln!("error: {}", e);
                        exit(1);
                    }
                }
            } else {
                eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                exit(1);
            }
        }
        ("list", Some(sub_m)) => {
            list_scripts(&config, sub_m);
        }
        ("move", Some(sub_m)) => {
            let from = sub_m.value_of("from-alias").unwrap();
            let to = sub_m.value_of("to-alias").unwrap();
            if !config.scripts.contains_key(from) {
                eprintln!("error: AliasNotFound: No script found by alias {}", from);
                exit(1);
            }
            if config.scripts.contains_key(to) && !sub_m.is_present("force") {
                eprintln!("error: AliasAlreadyExists:  {}", to);
                exit(1);
            }
            let script = config.scripts.remove(from).unwrap();
            config.scripts.insert(to.to_string(), script);
            config.save(&config_path).unwrap();
            println!("Move from alias {} to new alias {}", from, to);
        }
        ("remove", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap();
            if config.scripts.remove(alias).is_some() {
                config.save(&config_path).unwrap();
                println!("Removed {}", alias);
            } else {
                eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                exit(1);
            }
        }
        ("run", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap();
            let args: Vec<&str> = sub_m.values_of("args").unwrap_or_default().collect();
            if let Some(script) = config.scripts.get(alias) {
                run_script(alias, script, &args, verbose);
            } else {
                eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                exit(1);
            }
        }
        ("show", Some(sub_m)) => {
            let alias = sub_m.value_of("alias").unwrap();
            if let Some(script) = config.scripts.get(alias) {
                println!("{}", script.command);
            } else {
                eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                exit(1);
            }
        }
        _ => {
            if let Some(alias) = matches.value_of("alias") {
                let args: Vec<&str> = matches.values_of("args").unwrap_or_default().collect();
                if let Some(script) = config.scripts.get(alias) {
                    run_script(alias, script, &args, verbose);
                } else {
                    eprintln!("error: AliasNotFound: No script found by alias {}", alias);
                    exit(1);
                }
            } else {
                app.clone().print_help().unwrap();
                println!();
            }
        }
    }
}

fn config_init() {
    let xdg_config_home = env::var("XDG_CONFIG_HOME")
        .map(PathBuf::from)
        .ok()
        .or_else(|| dirs::home_dir().map(|h| h.join(".config")));
    if let Some(xdg) = xdg_config_home {
        let pier_dir = xdg.join("pier");
        if !pier_dir.exists() {
            if let Err(e) = fs::create_dir(&pier_dir) {
                eprintln!("error: Failed to create directory. {}", e);
                exit(1);
            }
        }
        let config_path = pier_dir.join("config.toml");
        if config_path.exists() {
            eprintln!("error: Cannot initialize config at {}, file already exists.", config_path.display());
            exit(1);
        }
        let mut config = Config::default();
        config.scripts.insert("hello-pier".to_string(), Script {
            command: "echo Hello, Pier!".to_string(),
            description: Some("This is an example command.".to_string()),
            tags: None,
        });
        if let Err(e) = config.save(&config_path) {
            eprintln!("error: Failed to save config. {}", e);
            exit(1);
        }
        println!("Added hello-pier");
    } else {
        eprintln!("error: Could not find config directory.");
        exit(1);
    }
}

fn list_scripts(config: &Config, sub_m: &clap::ArgMatches) {
    if config.scripts.is_empty() && !sub_m.is_present("tag") {
        eprintln!("error: No scripts exist. Would you like to add a new script?");
        exit(1);
    }
    if sub_m.is_present("list_aliases") {
        for alias in config.scripts.keys() {
            println!("{}", alias);
        }
        return;
    }
    let filter_tags: Vec<&str> = sub_m.values_of("tag").unwrap_or_default().collect();
    let mut alias_width = 5;
    let mut tags_width = 4;
    let mut cmd_width = 7;
    let mut desc_width = 11;
    let mut display_scripts = Vec::new();
    for (alias, script) in &config.scripts {
        if !filter_tags.is_empty() {
            let mut matched = false;
            if let Some(tags) = &script.tags {
                for ft in &filter_tags {
                    if tags.contains(&ft.to_string()) {
                        matched = true;
                        break;
                    }
                }
            }
            if !matched { continue; }
        }
        let tags = script.tags.as_ref().map(|t| t.join(",")).unwrap_or_default();
        let cmd = if sub_m.is_present("cmd_full") {
            script.command.clone()
        } else if let Some(width) = sub_m.value_of("cmd_width").and_then(|w| w.parse::<usize>().ok()) {
            script.command.chars().take(width).collect()
        } else if let Some(width) = config.default.command_width {
            script.command.chars().take(width).collect()
        } else {
            script.command.clone()
        };
        let desc = script.description.as_deref().unwrap_or_default().to_string();
        alias_width = alias_width.max(alias.len());
        tags_width = tags_width.max(tags.len());
        cmd_width = cmd_width.max(cmd.len());
        desc_width = desc_width.max(desc.len());
        display_scripts.push((alias, tags, cmd, desc));
    }
    let line: String = std::iter::repeat('\u{2256}').take(alias_width + tags_width + cmd_width + desc_width + 13).collect();
    println!("{}", line);
    println!("\u{22ee} {:<aw$} \u{22ee} {:<tw$} \u{22ee} {:<cw$} \u{22ee} {:<dw$} \u{22ee}", "Alias", "Tags", "Command", "Description", aw=alias_width, tw=tags_width, cw=cmd_width, dw=desc_width);
    println!("{}", line);
    for (alias, tags, cmd, desc) in display_scripts {
        println!("\u{22ee} {:<aw$} \u{22ee} {:<tw$} \u{22ee} {:<cw$} \u{22ee} {:<dw$} \u{22ee}", alias, tags, cmd, desc, aw=alias_width, tw=tags_width, cw=cmd_width, dw=desc_width);
    }
    println!("{}", line);
}

fn run_script(alias: &str, script: &Script, args: &[&str], verbose: bool) {
    if verbose {
        println!("Starting script \"{}\"", alias);
        println!("-------------------------");
    }
    let mut cmd = Command::new("sh");
    cmd.arg("-c").arg(&script.command).arg(alias);
    for arg in args {
        cmd.arg(arg);
    }
    let status = cmd.status();
    if verbose {
        println!("-------------------------");
        println!("Script complete");
    }
    match status {
        Ok(s) => {
            if let Some(code) = s.code() {
                exit(code);
            }
        }
        Err(e) => {
            eprintln!("error: {}", e);
            exit(1);
        }
    }
}
